def write_to_terminal(session_id, input_text, append_newline=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0221000" if __import__("os").path.isdir("./environment_mix/0221000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    _re_sess = re.compile(r"^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$")

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        time_val = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[time_val & 31])
            time_val >>= 5
        out = list(reversed(out))
        r = (time.time_ns() ^ (os.getpid() << 16) ^ int(time.perf_counter_ns())) & ((1 << 80) - 1)
        rnd = []
        for _ in range(16):
            rnd.append(alphabet[r & 31])
            r >>= 5
        rnd = list(reversed(rnd))
        return f"{prefix}_{''.join(out + rnd)}"

    def _pick_context_for_session(sessions, api_keys, session_id_value, tool):
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id_value), None)
        if not sess:
            return None, None, _err("NOT_FOUND", "Terminal session not found.")
        api_key_id = sess.get("api_key_id")
        if not isinstance(api_key_id, str) or not api_key_id:
            return None, None, _err("UNAUTHORIZED", "No authenticated API key context can serve this session.", rule="terminal_sessions.api_key_id references api_keys.id")
        key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
        if not key_row:
            return None, None, _err("UNAUTHORIZED", "API key referenced by session does not exist.", rule="fk(terminal_sessions.api_key_id) references api_keys.id")
        if key_row.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "Tool call rejected by business rule: api key must be active.", rule="api_keys.status == 'active'")
        scopes = key_row.get("scopes") if isinstance(key_row.get("scopes"), list) else []
        if tool not in scopes:
            return None, None, _err("UNAUTHORIZED", "Tool call rejected by business rule: api key missing required scope.", rule="api_keys.scopes contains tool_name")
        return sess, key_row, None

    def _upsert_usage_and_check(usage_rows, api_key_row, tool, now_dt):
        window_seconds = 60
        epoch = int(now_dt.timestamp())
        start_epoch = epoch - (epoch % window_seconds)
        window_start = datetime.datetime.fromtimestamp(start_epoch, tz=datetime.timezone.utc)
        window_start_iso = _iso(window_start)

        api_key_id = api_key_row.get("id")
        existing = None
        for r in usage_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == api_key_id and r.get("window_start_at") == window_start_iso and r.get("window_seconds") == window_seconds and r.get("tool_name") == tool:
                existing = r
                break

        if existing is None:
            existing = {
                "id": _gen_id("iterm_use"),
                "api_key_id": api_key_id,
                "window_start_at": window_start_iso,
                "window_seconds": window_seconds,
                "tool_name": tool,
                "call_count": 0,
                "error_count": 0,
                "created_at": _iso(now_dt),
                "updated_at": _iso(now_dt),
            }
            usage_rows.append(existing)

        current = existing.get("call_count") if isinstance(existing.get("call_count"), int) else 0
        limit_per_min = api_key_row.get("rate_limit_per_minute")
        if not isinstance(limit_per_min, int) or limit_per_min < 1:
            limit_per_min = 1

        if current + 1 > limit_per_min:
            remaining = (start_epoch + window_seconds) - epoch
            if remaining < 0:
                remaining = 0
            return False, remaining, window_start_iso, existing

        existing["call_count"] = current + 1
        existing["updated_at"] = _iso(now_dt)
        return True, None, window_start_iso, existing

    def _mark_usage_error(usage_row, now_dt):
        if usage_row is None:
            return
        ec = usage_row.get("error_count") if isinstance(usage_row.get("error_count"), int) else 0
        usage_row["error_count"] = ec + 1
        usage_row["updated_at"] = _iso(now_dt)

    # Validate inputs
    if not isinstance(session_id, str) or not _re_sess.match(session_id):
        return _err("VALIDATION_ERROR", "session_id must match ^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$.")
    if not isinstance(input_text, str) or input_text == "":
        return _err("VALIDATION_ERROR", "input_text must be a non-empty string.")
    if append_newline is not None and not isinstance(append_newline, bool):
        return _err("VALIDATION_ERROR", "append_newline must be a boolean when provided.")

    # Load store
    api_keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")
    events = _load("terminal_events.json")
    usage = _load("usage_counters.json")

    sess, key_row, ctx_err = _pick_context_for_session(sessions, api_keys, session_id, "write_to_terminal")
    if ctx_err:
        # Record failed event if we have a resolvable key/session; otherwise nothing to attach to.
        return ctx_err

    # Enforce session active/expiry (and transition to expired if needed)
    sess_status = sess.get("status")
    expires_at = _parse_dt(sess.get("expires_at"))
    if expires_at is not None and now >= expires_at and sess_status == "active":
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)
        sess_status = "expired"
        _save("terminal_sessions.json", sessions)

    if sess_status != "active":
        # Append-only event row even for rejected tool call
        evt = {
            "id": _gen_id("iterm_evt"),
            "session_id": sess.get("id"),
            "api_key_id": key_row.get("id"),
            "tool_name": "write_to_terminal",
            "status": "failed",
            "request_payload": {},
            "error_message": "session not active; tool call rejected" if sess_status != "expired" else "session expired; tool call rejected",
            "duration_ms": int((time.perf_counter() - t0) * 1000),
            "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(evt)
        _save("terminal_events.json", events)
        return _err("UNAUTHORIZED", "Tool call rejected by business rule: session must be active.", rule="terminal_sessions.status == 'active'")

    # Rate limit (upsert bucket, reject if would exceed)
    ok, retry_after, bucket_start, usage_row = _upsert_usage_and_check(usage, key_row, "write_to_terminal", now)
    if not ok:
        evt = {
            "id": _gen_id("iterm_evt"),
            "session_id": sess.get("id"),
            "api_key_id": key_row.get("id"),
            "tool_name": "write_to_terminal",
            "status": "failed",
            "request_payload": {},
            "error_message": f"rate limit exceeded; retry after {int(retry_after)}s",
            "duration_ms": int((time.perf_counter() - t0) * 1000),
            "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(evt)
        _save("terminal_events.json", events)
        _save("usage_counters.json", usage)
        return _err("RATE_LIMIT", "rate limit exceeded", retry_after_seconds=int(retry_after), bucket_window_start=bucket_start)

    # Perform "write" (offline): succeed and record event
    evt = {
        "id": _gen_id("iterm_evt"),
        "session_id": sess.get("id"),
        "api_key_id": key_row.get("id"),
        "tool_name": "write_to_terminal",
        "status": "succeeded",
        "request_payload": {},
        "error_message": None,
        "duration_ms": None,
        "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    # finalize duration
    evt["duration_ms"] = int((time.perf_counter() - t0) * 1000)

    events.append(evt)

    # Update activity timestamps
    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    _save("terminal_events.json", events)
    _save("terminal_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("usage_counters.json", usage)

    return {"terminal_event": evt}

def read_terminal_output(session_id, since_event_id=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0221000" if __import__("os").path.isdir("./environment_mix/0221000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    _re_sess = re.compile(r"^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$")
    _re_evt = re.compile(r"^iterm_evt_[0-9A-HJKMNP-TV-Z]{26}$")
    _order_enum = ("asc", "desc")

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        time_val = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[time_val & 31])
            time_val >>= 5
        out = list(reversed(out))
        r = (time.time_ns() ^ (os.getpid() << 16) ^ int(time.perf_counter_ns())) & ((1 << 80) - 1)
        rnd = []
        for _ in range(16):
            rnd.append(alphabet[r & 31])
            r >>= 5
        rnd = list(reversed(rnd))
        return f"{prefix}_{''.join(out + rnd)}"

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _pick_context_for_session(sessions, api_keys, session_id_value, tool):
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id_value), None)
        if not sess:
            return None, None, _err("NOT_FOUND", "Terminal session not found.")
        api_key_id = sess.get("api_key_id")
        if not isinstance(api_key_id, str) or not api_key_id:
            return None, None, _err("UNAUTHORIZED", "No authenticated API key context can serve this session.", rule="terminal_sessions.api_key_id references api_keys.id")
        key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
        if not key_row:
            return None, None, _err("UNAUTHORIZED", "API key referenced by session does not exist.", rule="fk(terminal_sessions.api_key_id) references api_keys.id")
        if key_row.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "Tool call rejected by business rule: api key must be active.", rule="api_keys.status == 'active'")
        scopes = key_row.get("scopes") if isinstance(key_row.get("scopes"), list) else []
        if tool not in scopes:
            return None, None, _err("UNAUTHORIZED", "Tool call rejected by business rule: api key missing required scope.", rule="api_keys.scopes contains tool_name")
        return sess, key_row, None

    def _upsert_usage_and_check(usage_rows, api_key_row, tool, now_dt):
        window_seconds = 60
        epoch = int(now_dt.timestamp())
        start_epoch = epoch - (epoch % window_seconds)
        window_start = datetime.datetime.fromtimestamp(start_epoch, tz=datetime.timezone.utc)
        window_start_iso = _iso(window_start)

        api_key_id = api_key_row.get("id")
        existing = None
        for r in usage_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == api_key_id and r.get("window_start_at") == window_start_iso and r.get("window_seconds") == window_seconds and r.get("tool_name") == tool:
                existing = r
                break

        if existing is None:
            existing = {
                "id": _gen_id("iterm_use"),
                "api_key_id": api_key_id,
                "window_start_at": window_start_iso,
                "window_seconds": window_seconds,
                "tool_name": tool,
                "call_count": 0,
                "error_count": 0,
                "created_at": _iso(now_dt),
                "updated_at": _iso(now_dt),
            }
            usage_rows.append(existing)

        current = existing.get("call_count") if isinstance(existing.get("call_count"), int) else 0
        limit_per_min = api_key_row.get("rate_limit_per_minute")
        if not isinstance(limit_per_min, int) or limit_per_min < 1:
            limit_per_min = 1

        if current + 1 > limit_per_min:
            remaining = (start_epoch + window_seconds) - epoch
            if remaining < 0:
                remaining = 0
            return False, remaining, window_start_iso, existing

        existing["call_count"] = current + 1
        existing["updated_at"] = _iso(now_dt)
        return True, None, window_start_iso, existing

    def _mark_usage_error(usage_row, now_dt):
        if usage_row is None:
            return
        ec = usage_row.get("error_count") if isinstance(usage_row.get("error_count"), int) else 0
        usage_row["error_count"] = ec + 1
        usage_row["updated_at"] = _iso(now_dt)

    # Validate inputs
    if not isinstance(session_id, str) or not _re_sess.match(session_id):
        return _err("VALIDATION_ERROR", "session_id must match ^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$.")
    if since_event_id is not None and (not isinstance(since_event_id, str) or not _re_evt.match(since_event_id)):
        return _err("VALIDATION_ERROR", "since_event_id must match ^iterm_evt_[0-9A-HJKMNP-TV-Z]{26}$ when provided.")
    if limit is None:
        limit_v = 30
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
        limit_v = limit
    if order is None:
        order_v = "asc"
    else:
        if not isinstance(order, str) or order not in _order_enum:
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
        order_v = order
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    api_keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")
    events = _load("terminal_events.json")
    snapshots = _load("terminal_output_snapshots.json")
    usage = _load("usage_counters.json")

    sess, key_row, ctx_err = _pick_context_for_session(sessions, api_keys, session_id, "read_terminal_output")
    if ctx_err:
        return ctx_err

    # Enforce session active/expiry for tool calls (reads are tool calls and must be rejected if session not active)
    sess_status = sess.get("status")
    expires_at = _parse_dt(sess.get("expires_at"))
    if expires_at is not None and now >= expires_at and sess_status == "active":
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)
        sess_status = "expired"
        _save("terminal_sessions.json", sessions)

    if sess_status != "active":
        evt = {
            "id": _gen_id("iterm_evt"),
            "session_id": sess.get("id"),
            "api_key_id": key_row.get("id"),
            "tool_name": "read_terminal_output",
            "status": "failed",
            "request_payload": {},
            "error_message": "session not active; tool call rejected" if sess_status != "expired" else "session expired; tool call rejected",
            "duration_ms": int((time.perf_counter() - t0) * 1000),
            "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(evt)
        _save("terminal_events.json", events)
        return _err("UNAUTHORIZED", "Tool call rejected by business rule: session must be active.", rule="terminal_sessions.status == 'active'")

    # Rate limit (this call counts too)
    ok, retry_after, bucket_start, usage_row = _upsert_usage_and_check(usage, key_row, "read_terminal_output", now)
    if not ok:
        evt = {
            "id": _gen_id("iterm_evt"),
            "session_id": sess.get("id"),
            "api_key_id": key_row.get("id"),
            "tool_name": "read_terminal_output",
            "status": "failed",
            "request_payload": {},
            "error_message": f"rate limit exceeded; retry after {int(retry_after)}s",
            "duration_ms": int((time.perf_counter() - t0) * 1000),
            "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(evt)
        _save("terminal_events.json", events)
        _save("usage_counters.json", usage)
        return _err("RATE_LIMIT", "rate limit exceeded", retry_after_seconds=int(retry_after), bucket_window_start=bucket_start)

    # Tool invocation must create exactly one terminal_events row.
    read_event = {
        "id": _gen_id("iterm_evt"),
        "session_id": sess.get("id"),
        "api_key_id": key_row.get("id"),
        "tool_name": "read_terminal_output",
        "status": "succeeded",
        "request_payload": {},
        "error_message": None,
        "duration_ms": None,
        "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    # In offline datastore, a successful read produces a snapshot row (unique per event).
    # We'll snapshot as empty output unless later extended.
    snapshot_text = ""  # must be non-null when status=stored
    snapshot_bytes = len(snapshot_text.encode("utf-8"))

    snap_row = {
        "id": _gen_id("iterm_out"),
        "event_id": read_event["id"],
        "session_id": sess.get("id"),
        "status": "stored",
        "output_text": snapshot_text,
        "output_bytes": snapshot_bytes,
        "content_encoding": "utf-8",
        "started_at": None,
        "ended_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Enforce unique(event_id)
    if any(isinstance(r, dict) and r.get("event_id") == snap_row["event_id"] for r in snapshots):
        # Should not happen for new ids; treat as conflict and mark usage error & event failed.
        read_event["status"] = "failed"
        read_event["error_message"] = "snapshot already exists for event"
        read_event["updated_at"] = _iso(now)
        read_event["duration_ms"] = int((time.perf_counter() - t0) * 1000)
        events.append(read_event)
        _mark_usage_error(usage_row, now)
        _save("terminal_events.json", events)
        _save("usage_counters.json", usage)
        return _err("CONFLICT", "unique(event_id) violated for terminal_output_snapshots.", rule="unique(event_id)")

    read_event["duration_ms"] = int((time.perf_counter() - t0) * 1000)
    events.append(read_event)
    snapshots.append(snap_row)

    # Update activity timestamps
    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    _save("terminal_events.json", events)
    _save("terminal_output_snapshots.json", snapshots)
    _save("terminal_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("usage_counters.json", usage)

    # Now serve the requested snapshots page from store (including the new one)
    rows = [r for r in snapshots if isinstance(r, dict) and r.get("session_id") == session_id]
    if since_event_id is not None:
        # Filter to output captured after this event id, using snapshot created_at relative to that event's created_at.
        since_evt = next((e for e in events if isinstance(e, dict) and e.get("id") == since_event_id), None)
        since_dt = _parse_dt(since_evt.get("created_at")) if since_evt else None
        if since_dt is not None:
            rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) > since_dt]
        else:
            # If event id not found, treat as empty filter result (not an error).
            rows = []

    def _sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=(order_v == "desc"))

    # Cursor is opaque; we encode the last seen sort key.
    start_index = 0
    if cursor is not None:
        cur = _b64d(cursor)
        if not isinstance(cur, dict) or "last_created_at" not in cur or "last_id" not in cur:
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        last_created_at = _parse_dt(cur.get("last_created_at"))
        last_id = cur.get("last_id")
        if last_created_at is None or not isinstance(last_id, str):
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        # Find first row after cursor depending on order
        def _after(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            rid = str(r.get("id") or "")
            if order_v == "asc":
                return (dt, rid) > (last_created_at, last_id)
            return (dt, rid) < (last_created_at, last_id)
        for i, r in enumerate(rows):
            if _after(r):
                start_index = i
                break
        else:
            start_index = len(rows)

    page = rows[start_index:start_index + limit_v]
    has_more = start_index + limit_v < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _b64e({"last_created_at": _iso(last.get("created_at")), "last_id": str(last.get("id") or "")})

    return {
        "terminal_output_snapshots": page,
        "page": {"limit": limit_v, "order": order_v, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor},
        "read_event": read_event,
    }

def send_control_character(session_id, control, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0221000" if __import__("os").path.isdir("./environment_mix/0221000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    _re_sess = re.compile(r"^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$")
    _controls = ("ctrl_c", "ctrl_d", "ctrl_z", "esc")

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        time_val = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[time_val & 31])
            time_val >>= 5
        out = list(reversed(out))
        r = (time.time_ns() ^ (os.getpid() << 16) ^ int(time.perf_counter_ns())) & ((1 << 80) - 1)
        rnd = []
        for _ in range(16):
            rnd.append(alphabet[r & 31])
            r >>= 5
        rnd = list(reversed(rnd))
        return f"{prefix}_{''.join(out + rnd)}"

    def _pick_context_for_session(sessions, api_keys, session_id_value, tool):
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id_value), None)
        if not sess:
            return None, None, _err("NOT_FOUND", "Terminal session not found.")
        api_key_id = sess.get("api_key_id")
        if not isinstance(api_key_id, str) or not api_key_id:
            return None, None, _err("UNAUTHORIZED", "No authenticated API key context can serve this session.", rule="terminal_sessions.api_key_id references api_keys.id")
        key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
        if not key_row:
            return None, None, _err("UNAUTHORIZED", "API key referenced by session does not exist.", rule="fk(terminal_sessions.api_key_id) references api_keys.id")
        if key_row.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "Tool call rejected by business rule: api key must be active.", rule="api_keys.status == 'active'")
        scopes = key_row.get("scopes") if isinstance(key_row.get("scopes"), list) else []
        if tool not in scopes:
            return None, None, _err("UNAUTHORIZED", "Tool call rejected by business rule: api key missing required scope.", rule="api_keys.scopes contains tool_name")
        return sess, key_row, None

    def _upsert_usage_and_check(usage_rows, api_key_row, tool, now_dt):
        window_seconds = 60
        epoch = int(now_dt.timestamp())
        start_epoch = epoch - (epoch % window_seconds)
        window_start = datetime.datetime.fromtimestamp(start_epoch, tz=datetime.timezone.utc)
        window_start_iso = _iso(window_start)

        api_key_id = api_key_row.get("id")
        existing = None
        for r in usage_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") == api_key_id and r.get("window_start_at") == window_start_iso and r.get("window_seconds") == window_seconds and r.get("tool_name") == tool:
                existing = r
                break

        if existing is None:
            existing = {
                "id": _gen_id("iterm_use"),
                "api_key_id": api_key_id,
                "window_start_at": window_start_iso,
                "window_seconds": window_seconds,
                "tool_name": tool,
                "call_count": 0,
                "error_count": 0,
                "created_at": _iso(now_dt),
                "updated_at": _iso(now_dt),
            }
            usage_rows.append(existing)

        current = existing.get("call_count") if isinstance(existing.get("call_count"), int) else 0
        limit_per_min = api_key_row.get("rate_limit_per_minute")
        if not isinstance(limit_per_min, int) or limit_per_min < 1:
            limit_per_min = 1

        if current + 1 > limit_per_min:
            remaining = (start_epoch + window_seconds) - epoch
            if remaining < 0:
                remaining = 0
            return False, remaining, window_start_iso, existing

        existing["call_count"] = current + 1
        existing["updated_at"] = _iso(now_dt)
        return True, None, window_start_iso, existing

    # Validate
    if not isinstance(session_id, str) or not _re_sess.match(session_id):
        return _err("VALIDATION_ERROR", "session_id must match ^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$.")
    if not isinstance(control, str) or control not in _controls:
        return _err("VALIDATION_ERROR", "control must be one of: ctrl_c, ctrl_d, ctrl_z, esc.")

    api_keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")
    events = _load("terminal_events.json")
    usage = _load("usage_counters.json")

    sess, key_row, ctx_err = _pick_context_for_session(sessions, api_keys, session_id, "send_control_character")
    if ctx_err:
        return ctx_err

    sess_status = sess.get("status")
    expires_at = _parse_dt(sess.get("expires_at"))
    if expires_at is not None and now >= expires_at and sess_status == "active":
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)
        sess_status = "expired"
        _save("terminal_sessions.json", sessions)

    if sess_status != "active":
        evt = {
            "id": _gen_id("iterm_evt"),
            "session_id": sess.get("id"),
            "api_key_id": key_row.get("id"),
            "tool_name": "send_control_character",
            "status": "failed",
            "request_payload": {},
            "error_message": "session not active; tool call rejected" if sess_status != "expired" else "session expired; tool call rejected",
            "duration_ms": int((time.perf_counter() - t0) * 1000),
            "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(evt)
        _save("terminal_events.json", events)
        return _err("UNAUTHORIZED", "Tool call rejected by business rule: session must be active.", rule="terminal_sessions.status == 'active'")

    ok, retry_after, bucket_start, usage_row = _upsert_usage_and_check(usage, key_row, "send_control_character", now)
    if not ok:
        evt = {
            "id": _gen_id("iterm_evt"),
            "session_id": sess.get("id"),
            "api_key_id": key_row.get("id"),
            "tool_name": "send_control_character",
            "status": "failed",
            "request_payload": {},
            "error_message": f"rate limit exceeded; retry after {int(retry_after)}s",
            "duration_ms": int((time.perf_counter() - t0) * 1000),
            "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        events.append(evt)
        _save("terminal_events.json", events)
        _save("usage_counters.json", usage)
        return _err("RATE_LIMIT", "rate limit exceeded", retry_after_seconds=int(retry_after), bucket_window_start=bucket_start)

    evt = {
        "id": _gen_id("iterm_evt"),
        "session_id": sess.get("id"),
        "api_key_id": key_row.get("id"),
        "tool_name": "send_control_character",
        "status": "succeeded",
        "request_payload": {},
        "error_message": None,
        "duration_ms": int((time.perf_counter() - t0) * 1000),
        "terminal_fingerprint": sess.get("active_terminal_fingerprint"),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    events.append(evt)

    sess["last_activity_at"] = _iso(now)
    sess["updated_at"] = _iso(now)
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    _save("terminal_events.json", events)
    _save("terminal_sessions.json", sessions)
    _save("api_keys.json", api_keys)
    _save("usage_counters.json", usage)

    return {"terminal_event": evt}

def get_current_identity(api_key, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0221000" if __import__("os").path.isdir("./environment_mix/0221000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _floor_window(now_dt, window_seconds):
        epoch = int(now_dt.timestamp())
        start = epoch - (epoch % window_seconds)
        return datetime.datetime.fromtimestamp(start, tz=datetime.timezone.utc)

    # Validate
    if not isinstance(api_key, str) or len(api_key) < 1:
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    keys = _load("api_keys.json")
    usage = _load("usage_counters.json")

    # Authenticate: match provided value against stored client-visible value or id.
    # Store has only key_hash (non-reversible), so we can only accept if caller passed the key id.
    k = next((r for r in keys if r.get("id") == api_key), None)
    if not k:
        return _err("UNAUTHORIZED", "API key is missing or invalid.")
    if k.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked or inactive.")

    now_iso = _now_iso()
    now_dt = _parse_dt(now_iso)
    window_seconds = 60
    wstart = _floor_window(now_dt, window_seconds).isoformat()

    # Collect current window counters for all tools
    tools = ("write_to_terminal", "read_terminal_output", "send_control_character")
    buckets = [
        u for u in usage
        if u.get("api_key_id") == k.get("id")
        and u.get("window_seconds") == window_seconds
        and u.get("window_start_at") == wstart
        and u.get("tool_name") in tools
    ]
    by_tool = {t: {"call_count": 0, "error_count": 0} for t in tools}
    for b in buckets:
        t = b.get("tool_name")
        if t in by_tool:
            by_tool[t] = {
                "call_count": int(b.get("call_count") or 0),
                "error_count": int(b.get("error_count") or 0),
            }

    return {
        "identity": {
            "api_key_id": k.get("id"),
            "label": k.get("label"),
            "status": k.get("status"),
            "scopes": k.get("scopes") if isinstance(k.get("scopes"), list) else [],
            "rate_limit_per_minute": k.get("rate_limit_per_minute"),
            "burst_limit": k.get("burst_limit"),
            "last_used_at": k.get("last_used_at"),
            "created_at": k.get("created_at"),
            "updated_at": k.get("updated_at"),
        },
        "usage": {
            "window_seconds": window_seconds,
            "window_start_at": wstart,
            "per_tool": by_tool,
        }
    }

def create_terminal_session(api_key, active_terminal_fingerprint, expires_in_seconds=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0221000" if __import__("os").path.isdir("./environment_mix/0221000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        # 48-bit timestamp (ms) + 80-bit randomness = 26 chars Crockford
        ms = int(time.time() * 1000)
        ts = ms & ((1 << 48) - 1)
        rand = int.from_bytes(os.urandom(10), "big")
        val = (ts << 80) | rand
        out = []
        for _ in range(26):
            out.append(_CROCKFORD[val & 31])
            val >>= 5
        return "".join(reversed(out))

    def _find_api_key(keys, token):
        # Authenticate by matching either id or a client-visible value. We do not have raw key material,
        # so the only feasible client-visible value is the record id itself.
        for k in keys:
            if k.get("id") == token:
                return k
        return None

    # ---- validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(active_terminal_fingerprint, str) or not active_terminal_fingerprint.strip():
        return _err("VALIDATION_ERROR", "active_terminal_fingerprint must be a non-empty string.")
    if expires_in_seconds is not None:
        if not isinstance(expires_in_seconds, int):
            return _err("VALIDATION_ERROR", "expires_in_seconds must be an integer.")
        if expires_in_seconds < 60 or expires_in_seconds > 86400:
            return _err("VALIDATION_ERROR", "expires_in_seconds must be between 60 and 86400.")

    keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")

    key = _find_api_key(keys, api_key)
    if not key or key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is missing, invalid, or revoked.")

    # No specific scope required for session creation; but if present, enforce known enum validity.
    scopes = key.get("scopes")
    if not isinstance(scopes, list):
        return _err("UNAUTHORIZED", "API key is missing required permissions.")
    # if caller has zero scopes, treat as unauthorized for service use
    if len(scopes) == 0:
        return _err("UNAUTHORIZED", "API key is missing required permissions.")

    # Backend binding prerequisite: must have a plausible fingerprint.
    fp = active_terminal_fingerprint.strip()
    if not fp:
        return _err("CONFLICT", "Cannot bind to an active iTerm terminal (missing fingerprint).")

    now = _now()
    exp_at = None
    if expires_in_seconds is not None:
        exp_at = now + datetime.timedelta(seconds=int(expires_in_seconds))

    # Attach semantics: if there's already an active session for this key and fingerprint, return it idempotently.
    for s in sessions:
        if s.get("api_key_id") == key.get("id") and s.get("status") == "active" and (s.get("active_terminal_fingerprint") == fp):
            # If it is already expired, transition to expired and do not attach.
            s_exp = _parse_dt(s.get("expires_at"))
            if s_exp is not None and now >= s_exp:
                # transition active -> expired
                s["status"] = "expired"
                s["updated_at"] = _iso(now)
                _save("terminal_sessions.json", sessions)
            else:
                # Optionally extend expires_at if requested and it would extend the session.
                changed = False
                if exp_at is not None:
                    cur_exp = _parse_dt(s.get("expires_at"))
                    if cur_exp is None or exp_at > cur_exp:
                        s["expires_at"] = _iso(exp_at)
                        changed = True
                if changed:
                    s["updated_at"] = _iso(now)
                    _save("terminal_sessions.json", sessions)
                # Update key last_used_at for successful authenticated call
                key["last_used_at"] = _iso(now)
                key["updated_at"] = _iso(now)
                _save("api_keys.json", keys)
                return {"terminal_session": s}

    sid = "iterm_sess_" + _ulid()
    row = {
        "id": sid,
        "api_key_id": key.get("id"),
        "status": "active",
        "active_terminal_fingerprint": fp,
        "last_activity_at": _iso(now),
        "expires_at": _iso(exp_at),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    sessions.append(row)
    _save("terminal_sessions.json", sessions)

    key["last_used_at"] = _iso(now)
    key["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    return {"terminal_session": row}

def list_terminal_sessions(api_key, status=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0221000" if __import__("os").path.isdir("./environment_mix/0221000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _find_api_key(keys, token):
        for k in keys:
            if k.get("id") == token:
                return k
        return None

    # validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if status is not None and status not in ("active", "ended", "expired"):
        return _err("VALIDATION_ERROR", "status must be one of: active, ended, expired.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
    if cursor is not None and (not isinstance(cursor, str)):
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")

    key = _find_api_key(keys, api_key)
    if not key or key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is missing, invalid, or revoked.")

    # decode cursor (opaque)
    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("offset") is not None:
                start = int(obj["offset"])
                if start < 0:
                    start = 0
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # filter by ownership and status
    rows = [s for s in sessions if s.get("api_key_id") == key.get("id")]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]

    # sort by last_activity_at
    def _sort_key(s):
        dt = _parse_dt(s.get("last_activity_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    rows.sort(key=_sort_key, reverse=(order == "desc"))

    total = len(rows)
    page = rows[start:start + limit]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # successful authenticated call bookkeeping
    now = _now()
    key["last_used_at"] = now.isoformat().replace("+00:00", "Z")
    key["updated_at"] = key["last_used_at"]
    _save("api_keys.json", keys)

    return {"terminal_sessions": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

