    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    _re_sess = re.compile(r"^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$")

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(session_id, str) or not _re_sess.match(session_id):
        return _err("VALIDATION_ERROR", "session_id must match ^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$.")

    api_keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")

    presented = api_key.strip()

    # Authenticate against client-visible value or id. Do NOT compare to key_hash.
    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == presented), None)
    if not key_row:
        return _err("UNAUTHORIZED", "API key is missing or invalid.")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked.", rule="api_keys.status == 'active'")

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        return _err("NOT_FOUND", "Terminal session not found.")

    if sess.get("api_key_id") != key_row.get("id"):
        return _err("UNAUTHORIZED", "Forbidden: session is not owned by the caller.", rule="terminal_sessions.api_key_id == authenticated api_keys.id")

    # expire on read if needed
    expires_at = _parse_dt(sess.get("expires_at"))
    if sess.get("status") == "active" and expires_at is not None and now >= expires_at:
        # transition to expired (legal) then refuse end because it's not active anymore
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)
        _save("terminal_sessions.json", sessions)
        return _err("VALIDATION_ERROR", "Terminal session is not active.", rule="terminal_sessions.status == 'active'")

    if sess.get("status") != "active":
        return _err("VALIDATION_ERROR", "Terminal session is not active.", rule="terminal_sessions.status == 'active'")

    # Transition active -> ended
    sess["status"] = "ended"
    sess["updated_at"] = _iso(now)

    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    _save("terminal_sessions.json", sessions)
    _save("api_keys.json", api_keys)

    return {"terminal_session": sess}

def list_terminal_events(api_key, session_id, tool_name=None, status=None, since_event_id=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0221000" if __import__("os").path.isdir("./environment_mix/0221000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    _re_sess = re.compile(r"^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$")
    _re_evt = re.compile(r"^iterm_evt_[0-9A-HJKMNP-TV-Z]{26}$")
    _tool_enum = ("write_to_terminal", "read_terminal_output", "send_control_character")
    _status_enum = ("succeeded", "failed")
    _order_enum = ("asc", "desc")

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(session_id, str) or not _re_sess.match(session_id):
        return _err("VALIDATION_ERROR", "session_id must match ^iterm_sess_[0-9A-HJKMNP-TV-Z]{26}$.")
    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in _tool_enum):
        return _err("VALIDATION_ERROR", "tool_name must be one of: write_to_terminal, read_terminal_output, send_control_character.")
    if status is not None and (not isinstance(status, str) or status not in _status_enum):
        return _err("VALIDATION_ERROR", "status must be one of: succeeded, failed.")
    if since_event_id is not None and (not isinstance(since_event_id, str) or not _re_evt.match(since_event_id)):
        return _err("VALIDATION_ERROR", "since_event_id must match ^iterm_evt_[0-9A-HJKMNP-TV-Z]{26}$ when provided.")
    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.")
        limit_v = limit
    if order is None:
        order_v = "asc"
    else:
        if not isinstance(order, str) or order not in _order_enum:
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
        order_v = order
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    api_keys = _load("api_keys.json")
    sessions = _load("terminal_sessions.json")
    events = _load("terminal_events.json")

    presented = api_key.strip()
    key_row = next((k for k in api_keys if isinstance(k, dict) and k.get("id") == presented), None)
    if not key_row:
        return _err("UNAUTHORIZED", "API key is missing or invalid.")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is revoked.", rule="api_keys.status == 'active'")

    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        return _err("NOT_FOUND", "Terminal session not found.")
    if sess.get("api_key_id") != key_row.get("id"):
        return _err("UNAUTHORIZED", "Forbidden: session is not owned by the caller.", rule="terminal_sessions.api_key_id == authenticated api_keys.id")

    # Filter
    rows = [e for e in events if isinstance(e, dict) and e.get("session_id") == session_id]
    if tool_name is not None:
        rows = [e for e in rows if e.get("tool_name") == tool_name]
    if status is not None:
        rows = [e for e in rows if e.get("status") == status]

    if since_event_id is not None:
        since_evt = next((e for e in events if isinstance(e, dict) and e.get("id") == since_event_id), None)
        since_dt = _parse_dt(since_evt.get("created_at")) if since_evt else None
        if since_dt is not None:
            rows = [e for e in rows if (_parse_dt(e.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) > since_dt]
        else:
            rows = []

    def _sort_key(e):
        dt = _parse_dt(e.get("created_at"))
        if dt is None:
            dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (dt, str(e.get("id") or ""))

    rows.sort(key=_sort_key, reverse=(order_v == "desc"))

    start_index = 0
    if cursor is not None:
        cur = _b64d(cursor)
        if not isinstance(cur, dict) or "last_created_at" not in cur or "last_id" not in cur:
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        last_created_at = _parse_dt(cur.get("last_created_at"))
        last_id = cur.get("last_id")
        if last_created_at is None or not isinstance(last_id, str):
            return _err("VALIDATION_ERROR", "cursor is invalid.")

        def _after(e):
            dt = _parse_dt(e.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            eid = str(e.get("id") or "")
            if order_v == "asc":
                return (dt, eid) > (last_created_at, last_id)
            return (dt, eid) < (last_created_at, last_id)

        for i, e in enumerate(rows):
            if _after(e):
                start_index = i
                break
        else:
            start_index = len(rows)

    page = rows[start_index:start_index + limit_v]
    has_more = start_index + limit_v < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _b64e({"last_created_at": _iso(last.get("created_at")), "last_id": str(last.get("id") or "")})

    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    return {"terminal_events": page, "page": {"limit": limit_v, "order": order_v, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}}
